html:
{#- PDC Cheque Receipt: acknowledgement handed to the customer for a post-dated cheque. -#}
<style>
	.pdc-rcpt { font-size: 13px; }
	.pdc-rcpt h2 { text-align: center; margin: 0; }
	.pdc-rcpt table { width: 100%; border-collapse: collapse; margin-top: 10px; }
	.pdc-rcpt td, .pdc-rcpt th { border: 1px solid #777; padding: 5px 7px; }
	.pdc-rcpt .num { text-align: right; }
	.pdc-rcpt .note { margin-top: 12px; font-size: 11px; color: #444; }
	.pdc-rcpt .sign { margin-top: 50px; text-align: right; }
</style>
<div class="pdc-rcpt">
	<h2>{{ doc.company }}</h2>
	<div style="text-align:center"><b>{{ _("Post-Dated Cheque Receipt") }}</b></div>
	<p>{{ _("Receipt No") }}: <b>{{ doc.name }}</b> &nbsp; {{ _("Date") }}: <b>{{ frappe.format(doc.posting_date, {"fieldtype": "Date"}) }}</b></p>
	<p>{{ _("Received from") }} <b>{{ doc.party_name }}</b> {{ _("the following cheque") }}:</p>
	<table>
		<tr><th>{{ _("Cheque No") }}</th><th>{{ _("Cheque Date") }}</th><th>{{ _("Bank / Branch") }}</th><th class="num">{{ _("Amount") }}</th></tr>
		<tr>
			<td>{{ doc.cheque_no }}</td>
			<td>{{ frappe.format(doc.cheque_date, {"fieldtype": "Date"}) }}</td>
			<td>{{ doc.bank_name or "" }}{% if doc.bank_branch %}, {{ doc.bank_branch }}{% endif %}</td>
			<td class="num">{{ frappe.format(doc.amount, {"fieldtype": "Currency"}) }}</td>
		</tr>
	</table>
	<p>{{ _("Amount in words") }}: {{ frappe.utils.money_in_words(doc.amount) }}</p>
	{%- if doc.references %}
	<table>
		<tr><th>{{ _("Against Invoice") }}</th><th>{{ _("Due Date") }}</th><th class="num">{{ _("Allocated") }}</th></tr>
		{%- for r in doc.references %}
		<tr><td>{{ r.reference_name }}</td><td>{{ frappe.format(r.due_date, {"fieldtype": "Date"}) }}</td>
			<td class="num">{{ frappe.format(r.allocated_amount, {"fieldtype": "Currency"}) }}</td></tr>
		{%- endfor %}
	</table>
	{%- endif %}
	<p class="note">{{ _("This receipt is subject to realisation of the cheque. If the cheque is dishonoured, the amount stays due along with any bank charges.") }}</p>
	<div class="sign">{{ _("Authorised Signature") }}</div>
</div>
